#include "bimob/unit_system.hpp"
#include "bimob/geometry_integrity.hpp"
#include "bimob/command_dispatcher.hpp"
#include <cassert>
#include <cmath>
#include <limits>
#include <type_traits>
#include <iostream>
static_assert(!std::is_convertible_v<nagaplas::units::Millimeters,nagaplas::units::Degrees>);
static_assert(!std::is_convertible_v<nagaplas::units::Degrees,nagaplas::units::Millimeters>);
void t1(){using namespace nagaplas::units;assert(mm_to_m(Millimeters(2500))==2.5);assert(m_to_mm(2.5).value()==2500);assert(area_mm2_to_m2(1e6).value()==1);assert(volume_mm3_to_m3(1e9).value()==1);assert(std::abs(deg_to_rad(Degrees(180)).value()-std::acos(-1.))<1e-12);assert(std::abs(rad_to_deg(Radians(std::acos(-1.))).value()-180)<1e-12);assert(normalize_0_360(Degrees(-90)).value()==270);assert(normalize_minus180_180(Degrees(270)).value()==-90);bool e=false;try{Millimeters(std::numeric_limits<double>::quiet_NaN());}catch(const std::invalid_argument&){e=true;}assert(e);e=false;try{Degrees(std::numeric_limits<double>::infinity());}catch(const std::invalid_argument&){e=true;}assert(e);}
void t2(){using namespace nagaplas::geometry;WallSegmentSpec w{"a",{{0,0},{100,0}},200,2700};assert(validate_wall(w).is_valid);w.axis.b.x=.99;assert(validate_wall(w).error_code==ErrorCode::SegmentTooShort);w.axis.b.x=100;w.thickness_mm=0;assert(validate_wall(w).error_code==ErrorCode::InvalidThickness);w.thickness_mm=-2;assert(validate_wall(w).error_code==ErrorCode::InvalidThickness);w.thickness_mm=200;w.height_mm=99;assert(validate_wall(w).error_code==ErrorCode::InvalidHeight);w.height_mm=2700;w.axis.a.x=NAN;assert(validate_wall(w).error_code==ErrorCode::NonFinite);w.axis.a.x=0;assert(classify_intersection({{0,0},{2,2}},{{0,2},{2,0}})==IntersectionKind::ProperIntersection);assert(classify_intersection({{0,0},{2,0}},{{1,0},{3,0}})==IntersectionKind::CollinearOverlap);assert(classify_intersection({{0,0},{1,0}},{{1,0},{1,1}})==IntersectionKind::EndpointTouch);assert(classify_intersection({{0,0},{1,0}},{{2,0},{3,0}})==IntersectionKind::Disjoint);assert(validate_contour({{0,0},{100,0},{100,100},{0,100}}).is_valid);assert(validate_contour({{0,0},{100,0},{120,100},{0,100}}).is_valid);assert(!validate_contour({{0,0},{100,100},{0,100},{100,0}}).is_valid);assert(validate_segments({w,WallSegmentSpec{"dup",{{0,0},{100,0}},200,2700}}).error_code==ErrorCode::DuplicateSegment);assert(validate_segments({w,WallSegmentSpec{"b",{{50,0},{150,0}},200,2700}}).error_code==ErrorCode::CollinearOverlap);}
void t3(){using namespace nagaplas::transactions;CommandDispatcher d;auto f=[](const std::string&,const std::string&p,std::string&o){o=p;return true;};assert(d.dispatch("p","r1","s1",f,0).scene_revision==1);assert(d.dispatch("p","r2","s2",f,0).code==ResultCode::RevisionMismatch);auto du=d.dispatch("p","r1","s1",f);assert(du.code==ResultCode::Duplicate&&du.is_duplicate);assert(d.dispatch("p","r1","different",f).code==ResultCode::IdempotencyConflict);assert(d.dispatch("p","r2","s2",f,1).scene_revision==2);d.reset("new");assert(d.revision()==0&&d.state()=="new");assert(d.dispatch("p","r1","s1",f,0).code==ResultCode::Applied);}
int main(){t1();t2();t3();std::cout<<"3 core foundation suites passed\n";}